#!/usr/bin/env bash
# Generated by Claude (AI-assisted).
#
# Assemble web/cloudflare/dist/ for Cloudflare Pages:
#
#   dist/<vol>/        each volume's student HTML that has been built
#   dist/lean/         Lean's runtime, shared by every volume: lean.js and the
#                      Init, Std and Lean library files the exercises import,
#                      packed (library-packs.json, library/pack-NNN.bin).
#                      lean.wasm is not here; it is too big for a static Pages
#                      file, so functions/lean/ serves it from R2.
#
# Build the book first with the runtime location and version baked in:
#   SFL_LEAN_RUNTIME=/lean/ SFL_LEAN_VERSION=<build id> make lf-student
# then:
#   web/cloudflare/build.sh <runtime dir>
# where <runtime dir> holds lean.js, lean-lib-files.json and lean-lib/ for that
# same build (public/lean-wasm/ of lean4-wasm-in-browser).

set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
root=$(cd "$here/../.." && pwd)
runtime=$(cd "${1:?usage: build.sh <runtime dir>}" && pwd)
dist="$here/dist"

rm -rf "$dist"
mkdir -p "$dist/lean"

volumes=()
for vol in lf hl ts; do
  if [ -d "$root/_out/$vol/student/html" ]; then
    cp -R "$root/_out/$vol/student/html" "$dist/$vol"
    volumes+=("$vol")
  fi
done
[ ${#volumes[@]} -gt 0 ] || { echo "no built volume under _out/<vol>/student/html" >&2; exit 1; }

cp "$runtime/lean.js" "$dist/lean/"
# The Init, Std and Lean library files, packed into a few gzip files with an
# index (pack_library.py); lean-worker.js unpacks them in the browser.
python3 "$here/pack_library.py" "$runtime" "$dist/lean"

cat > "$dist/_headers" <<'EOF'
# Lean's threads share memory, which browsers allow only on cross-origin
# isolated pages.  This copy of the book is a prototype, kept out of search
# results so that it never competes with the official book.
/*
  Cross-Origin-Opener-Policy: same-origin
  Cross-Origin-Embedder-Policy: require-corp
  Cross-Origin-Resource-Policy: same-origin
  X-Robots-Tag: noindex

/lean/*
  Cache-Control: public, max-age=86400
EOF

# Only lean.wasm needs the Function; everything else is served as static files.
cat > "$dist/_routes.json" <<'EOF'
{ "version": 1, "include": ["/lean/lean.wasm"], "exclude": [] }
EOF

links=""
for vol in "${volumes[@]}"; do
  title=$(sed -n 's:.*<title>\(.*\)</title>.*:\1:p' "$dist/$vol/index.html" | head -1)
  links+="      <li><a href=\"$vol/\">${title:-$vol}</a></li>"$'\n'
done
cat > "$dist/index.html" <<EOF
<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="robots" content="noindex">
    <title>SF in Lean, in the browser</title>
    <style>
      body { font: 17px/1.5 "Helvetica Neue", Arial, sans-serif; max-width: 40em; margin: 3em auto; padding: 0 16px; color: #1a1208; background: #fffdf6; }
      h1 { color: #6b0d0d; font-size: 1.6em; }
      a { color: #7a1a1a; }
      .note { padding: 0.6em 1em; border-left: 3px solid #a00; background: #f4f4f3; }
    </style>
  </head>
  <body>
    <h1>Software Foundations in Lean, with exercises that run in your browser</h1>
    <p class="note">This is an unofficial prototype. The book is
      <a href="https://github.com/plclub/sf-in-lean">Software Foundations in Lean</a>
      by the Penn PL Club, unchanged except for an editor added to each exercise. On a
      desktop browser, <em>Try it here</em> checks your proof with Lean running on your
      own machine. The first use downloads Lean, about 500&nbsp;MB, once.</p>
    <ul>
$links    </ul>
  </body>
</html>
EOF

echo "dist: $(find "$dist" -type f | wc -l | tr -d ' ') files, $(du -sh "$dist" | cut -f1)"
